              "text": "医学上将 35 岁以上的女性怀孕定义为高龄妊娠。随着年龄增长，卵巢功能逐渐下降，卵子质量也会有所降低。但这并不意味着高龄就不能健康怀孕，只是需要更多的关注和准备。"
