                  "保持健康体重，BMI 在 18.5-24 之间最佳",
                  "减少压力，焦虑会影响排卵",
                  "适当补充辅酶 Q10、DHEA 等（遵医嘱）",
                  "备孕 6 个月未孕就应就诊"
