// 按 slug 建立快速索引
export const articleBySlug = {};
articles.forEach(a => { articleBySlug[a.slug] = a; });

// 按分类筛选
export function getArticlesByCategory(category) {
  return articles.filter(a => a.category === category);
}

// 获取最新文章
export function getLatestArticles(limit = 10) {
  return [...articles].sort((a, b) => new Date(b.publishedAt) - new Date(a.publishedAt)).slice(0, limit);
}

// 获取热门文章（按浏览量）
export function getHotArticles(limit = 10) {
  return [...articles].sort((a, b) => b.viewCount - a.viewCount).slice(0, limit);
}

// 搜索文章
export function searchArticles(query) {
  const q = query.toLowerCase();
  return articles.filter(a =>
    a.title.toLowerCase().includes(q) ||
    a.summary.toLowerCase().includes(q) ||
    a.tags.some(t => t.toLowerCase().includes(q)) ||
    a.category.toLowerCase().includes(q)
  );
}

// 按标签筛选
export function getArticlesByTag(tag) {
  return articles.filter(a => a.tags.includes(tag));
}

// 获取所有标签
export function getAllTags() {
  const tagMap = {};
  articles.forEach(a => {
    a.tags.forEach(t => {
      tagMap[t] = (tagMap[t] || 0) + 1;
    });
  });
  return Object.entries(tagMap)
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count);
}

export default articles;
